const copy = ([summary, overview, howItWorks, features]: CopyInput): ReferenceCopy => ({ summary, overview, howItWorks, features: features.split('|') })
function game(id: string, slug: string, title: string, providerId: ProviderId, category: CategorySlug, sources: string[], tags: string[], relatedSlugs: string[], en: CopyInput, pt: CopyInput, es: CopyInput): ReferenceGame {
  return { id, slug, title, providerId, category, sources, tags, relatedSlugs,
    content: { en: copy(en), 'pt-BR': copy(pt), 'es-MX': copy(es) }, verifiedAt,
    artwork: { status: 'fallback', source: 'playliva-neutral', sourceUrl: null, rightsStatus: 'pending-rights', verifiedAt },
    availability: { status: 'unverified', market: 'BR', operatorEvidence: [] },
  }
}
